-- ----------------------------
-- Table structure for user_question_records
-- ----------------------------
DROP TABLE IF EXISTS `user_question_records`;
CREATE TABLE `user_question_records`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint UNSIGNED NOT NULL,
  `question_id` bigint UNSIGNED NOT NULL,
  `is_favorite` tinyint(1) NOT NULL DEFAULT 0,
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_question_records_user_question`(`user_id` ASC, `question_id` ASC) USING BTREE,
  INDEX `fk_user_question_records_question`(`question_id` ASC) USING BTREE,
  INDEX `idx_user_question_records_favorite`(`user_id` ASC, `is_favorite` ASC, `updated_at` ASC) USING BTREE,
  CONSTRAINT `fk_user_question_records_question` FOREIGN KEY (`question_id`) REFERENCES `questions` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_question_records_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

