INSERT INTO `ai_messages` VALUES (9, 1, 'user', '请你总结一下\n\n附件信息：{\"document_id\": 1, \"file_name\": \"第4章 项目集成管理 - 更新.pptx\", \"file_type\": \"pptx\", \"parse_status\": \"parsed\", \"text_length\": 17665, \"summary\": \"软件项目管理\\nSoftware project management\\n计算机学院 刘佳琦\\n/18\\n开篇案例 结局\\n行政总裁建议，将\\nNick\\n调往另一部门，但\\nNick\\n不同意。在没有考虑后果的情况下，首席执行官向\\nNick\\n提出让他离开公司并支付给他一笔遣散费。由于计划中的企业并购，首席执行官知道，无论如何他们都可能要让一些人离开。\\nNick\\n向首席执行官提出，他还有没有休完的两个月假期以及较高比例的股票期权。在与妻子商议后他发觉，如果辞职他将会得到\\n7\\n万多美元。于是\\nNick\\n接受了遣散方案。\\n有了这样\\n-\\n次失败的作为项目经理的经验之后，他觉得还是适合做一名技术专家。\\n而\\nJim\\n，在\"}', NULL, NULL, '2026-06-08 17:07:59');
INSERT INTO `ai_messages` VALUES (10, 1, 'assistant', '### 观察者模式总结\n\n**1. 核心定义**\n一种**一对多**的依赖关系：当一个对象（被观察者）的状态发生改变时，所有依赖于它的对象（观察者）都会收到通知并自动更新。\n\n**2. 核心角色**\n*   **Subject (被观察者/发布者)**：维护观察者列表，负责通知。\n*   **Observer (观察者/订阅者)**：定义更新接口，负责响应通知。\n\n**3. 主要优点**\n*   **解耦**：被观察者不需要知道观察者的具体细节，降低了代码耦合度。\n*   **扩展性强**：新增观察者时，无需修改被观察者代码，符合开闭原则。\n\n**4. 常见场景**\n*   **事件驱动系统**：按钮点击后触发多个事件监听器。\n*   **消息推送**：微信公众号/新闻APP，内容更新后所有订阅者收到通知。\n*   **GUI编程**：窗口大小改变，自动重绘子组件。', NULL, NULL, '2026-06-08 17:07:59');
