INSERT INTO `ai_messages` VALUES (12, 3, 'assistant', '基于提供的附件摘要，总结如下：\n\n1.  **文件背景**：软件项目管理课程第4章“项目集成管理”的演示文稿。\n2.  **开篇案例（结局）**：\n    *   **Nick**：因公司并购计划，CEO提出让其离职。Nick经过计算发现辞职收益（休完假期+股票期权）高于留任，于是接受遣散方案。\n    *   **决定**：Nick 认为不适合做项目经理，决定转做技术专家。\n    *   **Jim**：故事片段在摘要中未结束。\n\n**注**：提供的摘要仅包含开篇案例的结局，未包含第4章的具体知识点（如整合过程、工具等）。', NULL, NULL, '2026-06-08 17:09:11');
