INSERT INTO `question_answers` VALUES (66, 66, '项目集成管理是指为确保项目各项工作能够有机地协调和配合所开展的综合性和全局性的项目管理工作和过程。主要过程有：计划制定、计划执行和计划变更控制。', '{\"text\": \"项目集成管理是指为确保项目各项工作能够有机地协调和配合所开展的综合性和全局性的项目管理工作和过程。主要过程有：计划制定、计划执行和计划变更控制。\"}', 1);
