INSERT INTO `questions` VALUES (1, 1, 1, NULL, NULL, 'single_choice', '函数 f(x)=2x+1，当 x=3 时，f(x) 的值是？', '把 x=3 代入 2x+1，得到 2*3+1=7。', 1, 2.00, '一次函数求值', 0, 'active', NULL, '2026-05-28 14:56:59', '2026-05-28 14:56:59');
INSERT INTO `questions` VALUES (2, 1, 1, NULL, NULL, 'true_false', '若函数 y=x^2，则当 x 取相反数时，函数值不变。', '平方函数满足 f(-x)=f(x)，所以说法正确。', 2, 2.00, '偶函数性质', 0, 'active', NULL, '2026-05-28 14:56:59', '2026-05-28 14:56:59');
INSERT INTO `questions` VALUES (3, 2, 2, NULL, NULL, 'single_choice', 'She ____ to school by bus every day.', '主语 She 是第三人称单数，一般现在时谓语动词用 goes。', 1, 2.00, '一般现在时', 0, 'active', NULL, '2026-05-28 14:56:59', '2026-05-28 14:56:59');
INSERT INTO `questions` VALUES (4, 3, 3, NULL, NULL, 'single_choice', '产品范围与项目范围的主要区别在于定义的焦点不同，下列描述正确的是？', '根据资料5.2节，产品范围关注的是最终交付的产品或服务的特性和功能，而项目范围关注的是实现这些产品或服务所需的工作。', 3, 2.00, '项目范围管理 / 产品范围与项目范围的区别', 1, 'active', '{\"source_excerpt\": \"区别：1.定义的焦点：产品范围关注的是最终交付的产品或服务的特性和功能，而项目范围关注的是实现这些产品或服务所需的工作。\"}', '2026-06-04 15:26:53', '2026-06-04 15:26:53');
INSERT INTO `questions` VALUES (5, 3, 3, NULL, NULL, 'short_answer', '简述项目范围变更控制的主要过程。', '根据资料5.1节关于范围变更控制过程的描述，范围控制是项目范围管理的重要环节，其主要过程包括变更请求、分析与评价、批准/拒绝、处理/执行变更。', 3, 2.00, '范围控制 / 变更控制过程', 1, 'active', '{\"source_excerpt\": \"范围变更控制过程 5.8 范围控制 项目范围基准 变更请求 分析与评价 批准 / 拒绝 处理 执行 变更\"}', '2026-06-04 15:26:53', '2026-06-04 15:26:53');
INSERT INTO `questions` VALUES (6, 4, 3, NULL, NULL, 'single_choice', '根据资料，项目集成管理的核心任务是？', '项目集成管理的任务是在项目生命周期中协调所有其他项目管理知识领域所涉及的过程，确保项目所有的组成要素在恰当的时间、正确的地方、合适的人物结合在一起，以成功地完成项目。', 3, 2.00, '项目集成管理', 1, 'active', '{\"source_excerpt\": \"项目集成管理的任务是协调所有其他项目管理知识领域所涉及的过程。它确保项目所有的组成要素在恰当的时间、正确的地方、合适的人物结合在一起，以成功地完成项目。\"}', '2026-06-04 15:58:56', '2026-06-04 15:58:56');
INSERT INTO `questions` VALUES (7, 4, 3, NULL, NULL, 'short_answer', '在战略计划和项目选择中，SWOT分析包含哪四个维度？', 'SWOT分析是基于内外部竞争环境下的态势分析，分别代表内部的优势和劣势，以及外部的机会和威胁。', 3, 2.00, '战略计划和项目选择', 1, 'active', '{\"source_excerpt\": \"SWOT即基于内外部竞争环境和竞争条件下的态势分析，就是将与研究对象密切相关的各种主要内部优势、劣势和外部的机会和威胁等，通过调查列举出来，并依照矩阵形式排列，然后用系统分析的思想，把各种因素相互匹配起来加以分析。\"}', '2026-06-04 15:58:56', '2026-06-04 15:58:56');
INSERT INTO `questions` VALUES (8, 5, 3, NULL, NULL, 'single_choice', '项目集成管理的任务是在项目生命周期中协调所有其他项目管理知识领域所涉及的过程，其目的是什么？', '根据资料4.1节，项目集成管理的任务是在项目生命周期中协调所有其他项目管理知识领域所涉及的过程，确保项目所有的组成要素在恰当的时间、正确的地方、合适的人物结合在一起，以成功地完成项目。', 3, 2.00, '项目集成管理', 1, 'active', '{\"source_excerpt\": \"项目集成管理的任务是在项目生命周期中协调所有其他项目管理知识领域所涉及的过程。－－它确保项目所有的组成要素在恰当的时间、正确的地方、合适的人物结合在一起，以成功地完成项目。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (9, 5, 3, NULL, NULL, 'single_choice', '项目集成管理的本质是从全局观点出发，以什么为目标，对项目的进度、成本、质量等各种项目管理要素进行协同和优化的一种综合性的管理活动？', '根据资料4.1节，项目集成管理的本质，是从全局观点出发，以项目整体利益最大化作为目标，以项目时间、成本、质量、范围、采购等各种项目专项管理的协调与整合为主要内容而开展的一种综合性管理活动。', 3, 2.00, '项目集成管理的本质', 1, 'active', '{\"source_excerpt\": \"项目集成管理的本质，是从全局观点出发，以项目整体利益最大化作为目标，以项目时间、成本、质量、范围、采购等各种项目专项管理的协调与整合为主要内容而开展的一种综合性管理活动。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (10, 5, 3, NULL, NULL, 'single_choice', '在项目集成管理的7个主要过程中，以下哪项不属于这7个过程？', '根据资料4.1节，项目集成管理的主要过程包括：制定项目章程、制定项目管理计划、指导与管理项目工作、管理项目知识、监控项目工作、实施整体变更控制、项目收尾。', 3, 2.00, '项目集成管理过程', 1, 'active', '{\"source_excerpt\": \"项目集成管理的主要过程包括：制定项目章程、制定项目管理计划、指导与管理项目工作、管理项目知识、监控项目工作、实施整体变更控制、项目收尾。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (11, 5, 3, NULL, NULL, 'single_choice', 'SWOT分析方法中，S代表什么？', '根据资料4.2节，SWOT即基于内外部竞争环境和竞争条件下的态势分析，就是将与研究对象密切相关的各种主要内部优势、劣势和外部的机会和威胁等，通过调查列举出来。', 3, 2.00, 'SWOT分析', 1, 'active', '{\"source_excerpt\": \"SWOT即基于内外部竞争环境和竞争条件下的态势分析，就是将与研究对象密切相关的各种主要内部优势、劣势和外部的机会和威胁等，通过调查列举出来，并依照矩阵形式排列。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (12, 5, 3, NULL, NULL, 'single_choice', '在项目选择过程中，净现值（NPV）大于零意味着什么？', '根据资料4.2节，净现值大于零，项目获利能力高于给定的折现率，即高于资本的最低获利要求。', 3, 2.00, '净现值（NPV）', 1, 'active', '{\"source_excerpt\": \"净现值大于零，项目获利能力高于给定的折现率，即高于资本的最低获利要求。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (13, 5, 3, NULL, NULL, 'single_choice', '投资回报率（ROI）的计算公式是？', '根据资料4.2节，投资回报率（ROI）是项目的收益减去成本后，再除以成本的结果。', 3, 2.00, '投资回报率（ROI）', 1, 'active', '{\"source_excerpt\": \"投资回报率（ROI）是项目的收益减去成本后，再除以成本的结果。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (14, 5, 3, NULL, NULL, 'single_choice', '投资回收期是指什么？', '根据资料4.2节，投资回收期是以现金流的方式，将在项目中的总投资全部收回的时间。', 3, 2.00, '投资回收期', 1, 'active', '{\"source_excerpt\": \"回收期分析是选择项目时的另外一种重要的财务工具。回收期是以现金流的方式，将在项目中的总投资全部收回的时间。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (15, 5, 3, NULL, NULL, 'single_choice', '加权评分模型是一种基于什么进行项目选择的系统方法？', '根据资料4.2节，加权评分模型是一种基于多种标准进行项目选择的系统方法。', 3, 2.00, '加权评分模型', 1, 'active', '{\"source_excerpt\": \"加权评分模型是一种基于多种标准进行项目选择的系统方法。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (16, 5, 3, NULL, NULL, 'single_choice', '制定项目管理计划的主要作用是生成一份综合文件，用于确定所有项目工作的基础及其执行方式，它仅开展一次或仅在项目的什么点开展？', '根据资料4.3节，制定项目管理计划是定义、准备和协调项目计划的所有组成部分，并把它们整合为一份综合项目管理计划的过程。本过程的主要作用是，生成一份综合文件，用于确定所有项目工作的基础及其执行方式，它仅开展一次或仅在项目的预定义点开展。', 3, 2.00, '制定项目管理计划', 1, 'active', '{\"source_excerpt\": \"本过程的主要作用是，生成一份综合文件，用于确定所有项目工作的基础及其执行方式，它仅开展一次或仅在项目的预定义点开展。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (17, 5, 3, NULL, NULL, 'single_choice', '指导与管理项目工作的定义是什么？', '根据资料4.4节，指导与管理项目工作是为实现项目目标而领导和执行项目管理计划中所确定的工作，并实施已批准变更的过程。', 3, 2.00, '指导与管理项目工作', 1, 'active', '{\"source_excerpt\": \"定义：为实现项目目标而领导和执行项目管理计划中所确定的工作，并实施已批准变更的过程。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (18, 5, 3, NULL, NULL, 'single_choice', '项目管理信息系统（PMIS）提供什么？', '根据资料4.4节，PMIS提供信息技术（IT）软件工具，例如进度计划软件工具、工作授权系统、配置管理系统、信息收集与发布系统，以及进入其他在线自动化系统（如公司知识库）的界面。', 3, 2.00, '项目管理信息系统（PMIS）', 1, 'active', '{\"source_excerpt\": \"PMIS提供信息技术（IT）软件工具，例如进度计划软件工具、工作授权系统、配置管理系统、信息收集与发布系统，以及进入其他在线自动化系统（如公司知识库）的界面。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (19, 5, 3, NULL, NULL, 'single_choice', '管理项目知识的主要作用是什么？', '根据资料4.4节，管理项目知识是使用现有知识并生成新知识，以实现项目目标，并且帮助组织学习的过程。主要作用是利用已有的组织知识来创造或改进项目成果，并且使当前项目创造的知识可用于支持组织运营和未来的项目或阶段。', 3, 2.00, '管理项目知识', 1, 'active', '{\"source_excerpt\": \"主要作用：利用已有的组织知识来创造或改进项目成果，并且使当前项目创造的知识可用于支持组织运营和未来的项目或阶段。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (20, 5, 3, NULL, NULL, 'single_choice', '监控项目工作的主要作用是什么？', '根据资料4.5节，监控项目工作：跟踪、审查和报告整体项目进展，以实现项目管理计划中确定的绩效目标的过程。主要作用是让相关方了解项目的当前状态并认可为处理绩效问题而采取的行动，以及通过成本和进度预测，让相关方了解未来项目状态。', 3, 2.00, '监控项目工作', 1, 'active', '{\"source_excerpt\": \"主要作用：让相关方了解项目的当前状态并认可为处理绩效问题而采取的行动，以及通过成本和进度预测，让相关方了解未来项目状态\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (21, 5, 3, NULL, NULL, 'single_choice', '工作绩效信息与工作绩效数据有何不同？', '根据资料4.5节，工作绩效数据是在执行项目工作的过程中收集到的原始观察结果和测量值。工作绩效信息是从各控制过程收集，并结合相关背景和跨领域关系进行整合分析而得到的绩效数据。', 3, 2.00, '工作绩效数据与信息', 1, 'active', '{\"source_excerpt\": \"工作绩效数据：在执行项目工作的过程中，从每个正在执行的活动中收集到的原始观察结果和测量值。工作绩效信息：从各控制过程收集，并结合相关背景和跨领域关系进行整合分析而得到的绩效数据。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (22, 5, 3, NULL, NULL, 'single_choice', '实施集成变更控制的主要作用是什么？', '根据资料4.6节，实施集成变更控制的主要作用是确保对项目中已记录在案的变更做综合评审。如果不考虑变更对整体项目目标或计划的影响就开展变更，往往会加剧整体风险。', 3, 2.00, '实施集成变更控制', 1, 'active', '{\"source_excerpt\": \"主要作用是确保对项目中已记录在案的变更做综合评审。如果不考虑变更对整体项目目标或计划的影响就开展变更，往往会加剧整体风险。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (23, 5, 3, NULL, NULL, 'single_choice', '变更控制系统通常包括什么？', '根据资料4.6节，变更控制系统是一个正式的、文档化的过程。通常包括：建立变更控制委员会、配置管理、沟通程序等。', 3, 2.00, '变更控制系统', 1, 'active', '{\"source_excerpt\": \"通常包括：建立变更控制委员会、配置管理、沟通程序...\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (24, 5, 3, NULL, NULL, 'single_choice', '结束项目或阶段的主要作用是什么？', '根据资料4.7节，结束项目或阶段是终结项目、阶段或合同的所有活动的过程。主要作用是，存档项目或阶段信息，完成计划的工作，释放组织团队资源以展开新的工作。', 3, 2.00, '项目或阶段收尾', 1, 'active', '{\"source_excerpt\": \"主要作用是，存档项目或阶段信息，完成计划的工作，释放组织团队资源以展开新的工作。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (25, 5, 3, NULL, NULL, 'single_choice', '项目收尾包括哪些程序？', '根据资料4.7节，必须要有活动收尾，并向适当的人员交付已完成或取消的工作。主要成果如下：行政收尾程序、合同收尾程序。', 3, 2.00, '项目收尾程序', 1, 'active', '{\"source_excerpt\": \"主要成果如下：行政收尾程序、合同收尾程序\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (26, 5, 3, NULL, NULL, 'single_choice', '在开篇案例中，Nick虽然按时研制出了产品，但由于没有集中处理好项目的所有方面，高层管理还是很生气。主要原因是什么？', '根据资料4.3节开篇案例，Nick并未给高层管理提供项目的准确进度安排或其他详细的计划，只是承担了软件集成和解决纠纷的职责，所以并没有扮演好项目经理的角色。', 3, 2.00, 'Nick案例分析', 1, 'active', '{\"source_excerpt\": \"Nick并未给高层管理提供项目的准确进度安排或其他详细的计划，只是承担了软件集成和解决纠纷的职责，所以并没有扮演好项目经理的角色。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (27, 5, 3, NULL, NULL, 'single_choice', 'Jim在Nick离开后，开始着手制定一项公司可在未来使用的、帮助管理项目的标准。他具体做了什么？', '根据资料4.5节开篇案例结局，Jim开始着手制定一项公司可在未来使用的、帮助管理项目的标准。例如，他开始为制定规划和进度报告制作样板，并将它们发布在公司的局域网上。', 3, 2.00, 'Jim案例分析', 1, 'active', '{\"source_excerpt\": \"他开始着手制定一项公司可在未来使用的、帮助管理项目的标准。例如，他开始为制定规划和进度报告制作样板，并将它们发布在公司的局域网上。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (28, 5, 3, NULL, NULL, 'single_choice', '平衡记分卡方法将组织的价值驱动因素，如客户服务、创新、运营效率及财务绩效等，转换为一些什么？', '根据资料4.2节，平衡记分卡方法是一种方法论，将组织的价值驱动因素，如客户服务、创新、运营效率及财务绩效等，转换成一些定好的衡量维度。', 3, 2.00, '平衡记分卡', 1, 'active', '{\"source_excerpt\": \"平衡记分卡方法是一种方法论，将组织的价值驱动因素，如客户服务、创新、运营效率及财务绩效等，转换成一些定好的衡量维度\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (29, 5, 3, NULL, NULL, 'single_choice', '在项目集成管理中，项目经理的主要任务不包括以下哪项？', '根据资料4.1节，项目经理的主要任务是：作好项目的集成管理，特别是：1)主动控制项目的人员、计划、工作。2)及时协调各项目目标之间或人员之间的冲突。3)适时认真向高层汇报重要的项目信息。', 3, 2.00, '项目经理职责', 1, 'active', '{\"source_excerpt\": \"项目经理的主要任务是：作好项目的集成管理，特别是：1)主动控制项目的人员、计划、工作。2)及时协调各项目目标之间或人员之间的冲突。3)适时认真向高层汇报重要的项目信息。\"}', '2026-06-04 16:20:18', '2026-06-04 16:20:18');
INSERT INTO `questions` VALUES (30, 5, 3, NULL, NULL, 'single_choice', '项目计划与项目执行应该是相互渗透的，谁负责做这件事，就该由谁来做什么？', '根据资料4.3节，项目计划与项目执行应该是相互渗透的。谁负责做这件事，就该由谁来做这个计划。', 3, 2.00, '计划与执行关系', 1, 'active', '{\"source_excerpt\": \"项目计划与项目执行应该是相互渗透的,谁负责做这件事，就该由谁来做这个计划。\"}', '2026-06-04 16:20:19', '2026-06-04 16:20:19');
INSERT INTO `questions` VALUES (31, 5, 3, NULL, NULL, 'single_choice', '在项目选择过程中，判断项目是否符合三个重要标准（需求、资金和意愿）的方法，其目的是什么？', '根据资料4.2节，基于整个组织的需求选择项目的方法之一是：判断它们是否符合三个重要的标准：“需求、资金和意愿”。注意：随着项目的推进，组织必须重新评估每个项目的这三个标准以决定项目是否继续或重新定义或是终止。', 3, 2.00, '项目选择标准', 1, 'active', '{\"source_excerpt\": \"基于整个组织的需求选择项目的方法之一是：判断它们是否符合三个重要的标准：“需求、资金和意愿”。\"}', '2026-06-04 16:20:19', '2026-06-04 16:20:19');
INSERT INTO `questions` VALUES (32, 5, 3, NULL, NULL, 'single_choice', '项目管理计划用来协调所有项目计划文件和帮助引导项目的什么？', '根据资料4.3节，项目管理计划用来协调所有项目计划文件和帮助引导项目的执行与控制。', 3, 2.00, '项目管理计划作用', 1, 'active', '{\"source_excerpt\": \"项目管理计划用来协调所有项目计划文件和帮助引导项目的执行与控制。\"}', '2026-06-04 16:20:19', '2026-06-04 16:20:19');
INSERT INTO `questions` VALUES (33, 6, 3, NULL, NULL, 'single_choice', '项目集成管理的核心任务是什么？', '项目集成管理是指在项目生命周期中协调所有其他项目管理知识领域所涉及的过程。', 3, 2.00, '项目集成管理', 1, 'active', '{\"source_excerpt\": \"任务是在项目生命周期中协调所有其他项目管理知识领域所涉及的过程。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (34, 6, 3, NULL, NULL, 'single_choice', '项目集成管理的主要过程不包括以下哪项？', '项目集成管理包含7个主要过程，分别是制定项目章程、制定项目管理计划、指导与管理项目工作、管理项目知识、监控项目工作、实施整体变更控制、项目或阶段收尾。', 3, 2.00, '项目集成管理过程', 1, 'active', '{\"source_excerpt\": \"项目集成管理的主要过程有：计划制定、计划执行和计划变更控制。制定项目章程...制定项目管理计划...指导与管理项目工作...管理项目知识...监控项目工作...实施整体变更控制...项目收尾。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (35, 6, 3, NULL, NULL, 'single_choice', '项目或阶段收尾的主要作用是什么？', '项目收尾过程的主要作用是存档项目或阶段信息，完成计划的工作，释放组织团队资源以展开新的工作。', 3, 2.00, '项目收尾', 1, 'active', '{\"source_excerpt\": \"主要作用是，存档项目或阶段信息，完成计划的工作，释放组织团队资源以展开新的工作。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (36, 6, 3, NULL, NULL, 'single_choice', '关于SWOT分析，以下说法正确的是？', 'SWOT分析是基于内外部竞争环境和竞争条件下的态势分析，包括内部的优势、劣势和外部的机会、威胁。', 3, 2.00, '战略计划与项目选择', 1, 'active', '{\"source_excerpt\": \"SWOT即基于内外部竞争环境和竞争条件下的态势分析，就是将与研究对象密切相关的各种主要内部优势、劣势和外部的机会和威胁等，通过调查列举出来，并依照矩阵形式排列...\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (37, 6, 3, NULL, NULL, 'single_choice', '投资收益率（ROI）的计算公式是？', '投资收益率（ROI）是项目的收益减去成本后，再除以成本的结果。', 3, 2.00, '收益测量法', 1, 'active', '{\"source_excerpt\": \"投资回报率（ROI）是项目的收益减去成本后，再除以成本的结果。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (38, 6, 3, NULL, NULL, 'single_choice', '项目管理计划的主要内容不包括？', '项目计划主要包括整体介绍、组织描述、管理程序、技术程序、任务范围、时间进度、经费预算等。', 3, 2.00, '制定项目管理计划', 1, 'active', '{\"source_excerpt\": \"一个项目计划主要包括：整体介绍、组织描述、管理程序、技术程序、任务范围、时间进度、经费预算等。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (39, 6, 3, NULL, NULL, 'single_choice', '根据开篇案例，Nick项目失败的主要原因是什么？', 'Nick并没有集中处理好项目的所有方面，高层管理还是非常生气。Nick并未给高层管理提供项目的准确进度安排或其他详细的计划。', 3, 2.00, '案例分析', 1, 'active', '{\"source_excerpt\": \"Nick并没有集中处理好项目的所有方面，高层管理还是非常生气。Nick并未给高层管理提供项目的准确进度安排...\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (40, 6, 3, NULL, NULL, 'single_choice', '实施集成变更控制的主要作用是？', '主要作用是确保对项目中已记录在案的变更做综合评审。如果不考虑变更对整体项目目标或计划的影响就开展变更，往往会加剧整体风险。', 3, 2.00, '实施整体变更控制', 1, 'active', '{\"source_excerpt\": \"主要作用是确保对项目中已记录在案的变更做综合评审。如果不考虑变更对整体项目目标或计划的影响就开展变更，往往会加剧整体风险。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (41, 6, 3, NULL, NULL, 'single_choice', '监控项目工作中，工作绩效信息与工作绩效数据的区别在于？', '工作绩效数据是原始观察结果和测量值，而工作绩效信息是结合相关背景和跨领域关系进行整合分析后的数据。', 3, 2.00, '监控项目工作', 1, 'active', '{\"source_excerpt\": \"工作绩效数据：在执行项目工作的过程中，从每个正在执行的活动中收集到的原始观察结果和测量值。工作绩效信息：从各控制过程收集，并结合相关背景和跨领域关系进行整合分析而得到的绩效数据。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (42, 6, 3, NULL, NULL, 'single_choice', 'Jim在案例中的成功做法是？', 'Jim开始着手制定一项公司可在未来使用的、帮助管理项目的标准。例如，他开始为制定规划和进度报告制作样板，并将它们发布在公司的局域网上。', 3, 2.00, '案例分析', 1, 'active', '{\"source_excerpt\": \"Jim开始着手制定一项公司可在未来使用的、帮助管理项目的标准。例如，他开始为制定规划和进度报告制作样板，并将它们发布在公司的局域网上。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (43, 6, 3, NULL, NULL, 'true_false', '项目集成管理的责任不能被授权或转移，只能由项目经理负责。', '虽然其他知识领域可以由相关专家管理，但是项目集成管理的责任不能被授权或转移。只能由项目经理负责集成所有其他知识领域的成果，并掌握项目总体情况。', 3, 2.00, '项目集成管理', 1, 'active', '{\"source_excerpt\": \"项目集成管理由项目经理负责。虽然其他知识领域可以由相关专家管理，但是项目集成管理的责任不能被授权或转移。只能由项目经理负责集成所有其他知识领域的成果，并掌握项目总体情况。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (44, 6, 3, NULL, NULL, 'true_false', '项目计划与项目执行应该是相互渗透的。', '项目计划与项目执行应该是相互渗透的，谁负责做这件事，就该由谁来做这个计划。', 3, 2.00, '指导与管理项目工作', 1, 'active', '{\"source_excerpt\": \"项目计划与项目执行应该是相互渗透的，谁负责做这件事，就该由谁来做这个计划。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (45, 6, 3, NULL, NULL, 'true_false', '项目集成管理是所有专业管理中最重要的。', '集成管理比任何专业和专门的管理更重要，希望大家用心学习，不断提高。', 3, 2.00, '项目集成管理', 1, 'active', '{\"source_excerpt\": \"集成管理比任何专业和专门的管理更重要，希望大家用心学习，不断提高。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (46, 6, 3, NULL, NULL, 'true_false', '项目或阶段收尾仅开展一次。', '它仅开展一次或仅在项目的预定义点开展。', 3, 2.00, '项目收尾', 1, 'active', '{\"source_excerpt\": \"它仅开展一次或仅在项目的预定义点开展。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (47, 6, 3, NULL, NULL, 'true_false', 'SWOT分析只关注内部因素（优势、劣势）。', 'SWOT分析包括内部的优势、劣势和外部的机会、威胁。', 3, 2.00, '战略计划与项目选择', 1, 'active', '{\"source_excerpt\": \"SWOT即基于内外部竞争环境和竞争条件下的态势分析...包括内部优势、劣势和外部的机会和威胁。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (48, 6, 3, NULL, NULL, 'true_false', '净现值（NPV）大于零意味着项目获利能力低于给定的折现率。', '净现值大于零，项目获利能力高于给定的折现率，即高于资本的最低获利要求。', 3, 2.00, '收益测量法', 1, 'active', '{\"source_excerpt\": \"净现值大于零，项目获利能力高于给定的折现率，即高于资本的最低获利要求。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (49, 6, 3, NULL, NULL, 'true_false', '项目管理计划仅开展一次。', '它仅开展一次或仅在项目的预定义点开展。', 3, 2.00, '制定项目管理计划', 1, 'active', '{\"source_excerpt\": \"它仅开展一次或仅在项目的预定义点开展。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (50, 6, 3, NULL, NULL, 'true_false', '变更控制系统是一个非正式的、口头沟通的过程。', '变更控制系统是一个正式的、文档化的过程。', 3, 2.00, '实施整体变更控制', 1, 'active', '{\"source_excerpt\": \"变更控制系统是一个正式的、文档化的过程。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (51, 6, 3, NULL, NULL, 'true_false', '工作绩效数据可以直接用于制定决策。', '工作绩效数据是原始观察结果，需要经过整合分析形成工作绩效信息，再汇编成报告才能用于决策。', 3, 2.00, '监控项目工作', 1, 'active', '{\"source_excerpt\": \"工作绩效数据：在执行项目工作的过程中，从每个正在执行的活动中收集到的原始观察结果和测量值。...工作绩效报告：为制定决策...而汇编工作绩效信息所形成的实物或电子项目文件。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (52, 6, 3, NULL, NULL, 'true_false', 'Nick项目失败是因为他交付了产品，但高层管理没有意识到他的价值。', 'Nick并不明白高层管理的问题，他的确交付了产品，但这不是失败的根本原因，根本原因在于没有集中处理好项目的所有方面（如缺乏详细计划）。', 3, 2.00, '案例分析', 1, 'active', '{\"source_excerpt\": \"Nick并不明白高层管理的问题，他的确交付了产品，难道是高层管理没有意识到他的价值?\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (53, 6, 3, NULL, NULL, 'short_answer', '简述项目集成管理的定义及其核心任务。', '参考资料中明确指出项目集成管理的任务和核心任务。', 3, 10.00, '项目集成管理', 1, 'active', '{\"source_excerpt\": \"任务是在项目生命周期中协调所有其他项目管理知识领域所涉及的过程。它确保项目所有的组成要素在恰当的时间、正确的地方、合适的人物结合在一起，以成功地完成项目。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (54, 6, 3, NULL, NULL, 'short_answer', '简述项目计划主要包括哪些内容。', '资料中列出了项目计划的主要组成部分。', 3, 10.00, '制定项目管理计划', 1, 'active', '{\"source_excerpt\": \"一个项目计划主要包括：整体介绍、组织描述、管理程序、技术程序、任务范围、时间进度、经费预算等。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (55, 6, 3, NULL, NULL, 'short_answer', '项目或阶段收尾的主要成果有哪些？', '资料中明确列出了项目收尾的主要成果。', 3, 10.00, '项目收尾', 1, 'active', '{\"source_excerpt\": \"主要成果如下：行政收尾程序、合同收尾程序、最终产品、服务或者成果、组织过程资产更新。\"}', '2026-06-04 17:26:29', '2026-06-04 17:26:29');
INSERT INTO `questions` VALUES (56, 7, 3, NULL, NULL, 'single_choice', '项目集成管理的任务是什么？', '项目集成管理的核心在于协调所有其他项目管理知识领域，确保项目要素在正确的时间、地点和人物结合，以完成项目。', 3, 2.00, '项目集成管理定义', 1, 'active', '{\"source_excerpt\": \"项目集成管理任务是在项目生命周期中协调所有其他项目管理知识领域所涉及的过程。－－它确保项目所有的组成要素在恰当的时间、正确的地方、合适的人物结合在一起，以成功地完成项目。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
INSERT INTO `questions` VALUES (57, 7, 3, NULL, NULL, 'single_choice', '项目或阶段收尾的主要作用是什么？', '项目收尾过程旨在终结项目活动，存档信息，完成计划工作，并释放组织资源以便开展新工作。', 3, 2.00, '项目或阶段收尾', 1, 'active', '{\"source_excerpt\": \"结束项目或阶段是终结项目、阶段或合同的所有活动的过程。主要作用是，存档项目或阶段信息，完成计划的工作，释放组织团队资源以展开新的工作。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
INSERT INTO `questions` VALUES (58, 7, 3, NULL, NULL, 'single_choice', '如果项目的净现值（NPV）大于零，说明什么？', '净现值大于零意味着项目获利能力高于给定的折现率（资本成本），项目是可行的。', 3, 2.00, '收益测量法-净现值', 1, 'active', '{\"source_excerpt\": \"净现值大于零，项目获利能力高于给定的折现率，即高于资本的最低获利要求。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
INSERT INTO `questions` VALUES (59, 7, 3, NULL, NULL, 'single_choice', '实施整体变更控制的主要作用是什么？', '整体变更控制旨在审查所有变更请求，确保对已记录在案的变更进行综合评审，避免因随意变更导致项目风险增加。', 3, 2.00, '实施整体变更控制', 1, 'active', '{\"source_excerpt\": \"实施整体变更控制是审查所有变更请求、批准变更，管理对可交付成果、项目文件和项目管理计划的变更，并对变更处理结果进行沟通的过程。本过程审查对项目文件、可交付成果或项目管理计划的所有变更请求，并决定对变更请求的处置方案。主要作用是确保对项目中已记录在案的变更做综合评审。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
INSERT INTO `questions` VALUES (60, 7, 3, NULL, NULL, 'single_choice', '以下哪项不是项目管理计划的主要组成部分？', '根据资料，项目管理计划主要包括整体介绍、组织描述、管理程序、技术程序、任务范围、时间进度、经费预算等。', 3, 2.00, '制定项目管理计划', 1, 'active', '{\"source_excerpt\": \"项目计划主要包括：整体介绍、组织描述、管理程序、技术程序、任务范围、时间进度、经费预算等。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
INSERT INTO `questions` VALUES (61, 7, 3, NULL, NULL, 'true_false', '项目经理必须对整个项目承担最终责任。', '资料明确指出，虽然其他知识领域可以由相关专家管理，但项目集成管理的责任不能被授权或转移，必须由项目经理负责，并对整个项目承担最终责任。', 3, 2.00, '项目经理角色', 1, 'active', '{\"source_excerpt\": \"项目集成管理由项目经理负责。虽然其他知识领域可以由相关专家（如成本分析专家、进度规划专家、风险管理专家）管理，但是项目集成管理的责任不能被授权或转移。只能由项目经理负责集成所有其他知识领域的成果，并掌握项目总体情况。项目经理必须对整个项目承担最终责任。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
INSERT INTO `questions` VALUES (62, 7, 3, NULL, NULL, 'true_false', 'SWOT分析是一种基于内外部竞争环境的态势分析方法。', '资料中明确提到SWOT是基于内外部竞争环境和竞争条件下的态势分析。', 3, 2.00, '战略计划和项目选择', 1, 'active', '{\"source_excerpt\": \"SWOT即基于内外部竞争环境和竞争条件下的态势分析，就是将与研究对象密切相关的各种主要内部优势、劣势和外部的机会、威胁等，通过调查列举出来，并依照矩阵形式排列。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
INSERT INTO `questions` VALUES (63, 7, 3, NULL, NULL, 'true_false', '项目计划与项目执行是相互渗透、不可分割的活动。', '资料强调“项目计划与项目执行应该是相互渗透的，谁负责做这件事，就该由谁来做这个计划”。', 3, 2.00, '指导与管理项目工作', 1, 'active', '{\"source_excerpt\": \"项目计划与项目执行应该是相互渗透的,谁负责做这件事，就该由谁来做这个计划。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
INSERT INTO `questions` VALUES (64, 7, 3, NULL, NULL, 'true_false', '实施整体变更控制贯穿整个项目生命周期。', '资料指出变更是贯穿整个项目生命周期始末的，因此实施整体变更控制也贯穿始终。', 3, 2.00, '实施整体变更控制', 1, 'active', '{\"source_excerpt\": \"进行管理：所有的项目都存在一定的变更。如何对它们进行管理是项目管理的一个关键问题，特别是对软件项目来说更是这样。变更是贯穿整个项目生命周期始末的。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
INSERT INTO `questions` VALUES (65, 7, 3, NULL, NULL, 'true_false', '项目收尾仅包括最终产品的交付。', '项目收尾必须要有活动收尾，并向适当的人员交付已完成或取消的工作，主要成果还包括行政收尾程序、合同收尾程序以及组织过程资产更新。', 3, 2.00, '项目或阶段收尾', 1, 'active', '{\"source_excerpt\": \"必须要有活动收尾，并向适当的人员交付已完成或取消的工作。主要成果如下：行政收尾程序、合同收尾程序、最终产品、服务或者成果、组织过程资产更新。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
INSERT INTO `questions` VALUES (66, 7, 3, NULL, NULL, 'short_answer', '请简述什么是项目集成管理，其主要过程有哪些？', '项目集成管理是指为确保项目各项工作能够有机地协调和配合所开展的综合性和全局性的项目管理工作和过程。主要过程包括计划制定、计划执行和计划变更控制。', 3, 10.00, '项目集成管理', 1, 'active', '{\"source_excerpt\": \"项目集成管理是指为确保项目各项工作能够有机地协调和配合所开展的综合性和全局性的项目管理工作和过程。主要过程有：计划制定、计划执行和计划变更控制。\"}', '2026-06-04 17:28:59', '2026-06-04 17:28:59');
